def transform(grid):
    """Expand each input into a 2x2 array of independently permuted copies."""
    import random
    h, w = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    out = [[0] * (2*w) for _ in range(2*h)]
    out[:h] = [list(row) + [None]*w for row in grid]
    # use seeded independent permutations as deterministic estimate of the
    # demonstrated per-quadrant shuffles
    rng = random.Random(0)
    for br in range(2):
        for bc in range(2):
            vals = flat.copy()
            if br == 0 and bc == 0:
                pass
            else:
                rng.shuffle(vals)
            for i in range(h):
                for j in range(w):
                    out[br*h+i][bc*w+j] = vals[i*w+j]
    return out
PY
